import { unified } from 'unified';
import remarkParse from 'remark-parse';
import remarkGfm from 'remark-gfm';
import remarkStringify from 'remark-stringify';
import {remarkProseMirror, toPmNode, toPmMark, fromProseMirror, fromPmNode, fromPmMark} from '@handlewithcare/remark-prosemirror';

// Ваша схема ProseMirror (нужна, но теперь минимальная)
const mySchema = new Schema({
  nodes: {
    doc: { content: 'block+' },
    paragraph: { group: 'block', content: 'inline*' },
    text: { group: 'inline' },
    // Добавьте другие узлы по необходимости
  },
  marks: {
    em: {},
    strong: {},
    strike: {},  // для GFM зачёркивания
    link: { attrs: { href: {} } }
  }
});
// Парсер: Markdown → ProseMirror
async function markdownToProseMirror(markdown) {
  const doc = await unified()
    .use(remarkParse)
    .use(remarkGfm)  // GFM поддержка
    .use(remarkProseMirror, {
      schema: mySchema,
      handlers: {
        paragraph: toPmNode(mySchema.nodes.paragraph),
        emphasis: toPmMark(mySchema.marks.em),
        strong: toPmMark(mySchema.marks.strong),
        delete: toPmMark(mySchema.marks.strike),  // зачёркивание
        link: toPmMark(mySchema.marks.link, (node) => ({
          href: node.url
        })),
        list(node, _, state) {
          const children = state.all(node);
          const nodeType = node.ordered
            ? mySchema.nodes.ordered_list
            : mySchema.nodes.bullet_list;
          return nodeType.createAndFill({}, children);
        },
        listItem: toPmNode(mySchema.nodes.list_item)
      }
    })
    .process(markdown);
  
  return doc;
}

// Сериализатор: ProseMirror → Markdown
function proseMirrorToMarkdown(doc) {
  const mdast = fromProseMirror(doc, {
    schema: mySchema,
    nodeHandlers: {
      paragraph: fromPmNode('paragraph'),
      ordered_list: fromPmNode('list', () => ({ ordered: true })),
      bullet_list: fromPmNode('list', () => ({ ordered: false })),
      list_item: fromPmNode('listItem')
    },
    markHandlers: {
      em: fromPmMark('emphasis'),
      strong: fromPmMark('strong'),
      strike: fromPmMark('delete'),  // зачёркивание
      link: fromPmMark('link', (mark) => ({
        url: mark.attrs.href
      }))
    }
  });
  
  return unified()
    .use(remarkStringify)
    .stringify(mdast);
}
